function sequential_lll(P, A):
  for all P in \mathcal{P}: v_P ← random evaluation of P
  while ∃ A ∈ \mathcal{A} : A is violated under (v_P):
    pick an arbitrary violated event A
    for all P ∈ vbl(A): v_P ← fresh random evaluation of P
  return (v_P)_{P ∈ \mathcal{P}}

function parallel_lll(P, A):
  for all P in \mathcal{P} in parallel: v_P ← random evaluation of P
  while ∃ A ∈ \mathcal{A} : A is violated under (v_P):
    S ← maximal independent set in G_A induced by violated events (built in parallel)
    for all P ∈ ∪_{A∈S} vbl(A) in parallel: v_P ← fresh random evaluation of P
  return (v_P)_{P ∈ \mathcal{P}}
